using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class HashRing
{
    private readonly int _replicas;
    private SortedDictionary<uint, string> _ring = new();

    public HashRing(IEnumerable<string> nodes, int replicas)
    {
        _replicas = replicas;
        foreach (var node in nodes)
        {
            AddNode(node);
        }
    }

    private static uint HashOf(string s)
    {
        using var md5 = MD5.Create();
        var digest = md5.ComputeHash(Encoding.UTF8.GetBytes(s));
        return (uint)((digest[0] << 24) | (digest[1] << 16) | (digest[2] << 8) | digest[3]);
    }

    public void AddNode(string node)
    {
        for (int i = 0; i < _replicas; i++)
        {
            _ring[HashOf($"{node}:{i}")] = node;
        }
    }

    public void RemoveNode(string node)
    {
        for (int i = 0; i < _replicas; i++)
        {
            _ring.Remove(HashOf($"{node}:{i}"));
        }
    }

    public string GetNode(string key)
    {
        var point = HashOf(key);
        foreach (var kv in _ring)
        {
            if (kv.Key >= point)
            {
                return kv.Value;
            }
        }
        return _ring.First().Value;
    }
}

