using System.Collections.Generic;
using System.Linq;
using Xunit;

public class HashRingTests
{
    [Fact]
    public void EveryKeyMapsToACurrentNode()
    {
        var ring = new HashRing(new[] { "a", "b", "c" }, 50);
        for (int i = 0; i < 200; i++)
        {
            var node = ring.GetNode($"key-{i}");
            Assert.Contains(node, new[] { "a", "b", "c" });
        }
    }

    [Fact]
    public void Deterministic()
    {
        var ring = new HashRing(new[] { "a", "b", "c" }, 50);
        Assert.Equal(ring.GetNode("stable-key"), ring.GetNode("stable-key"));
    }

    [Fact]
    public void RemovingANodeOnlyMovesThatNodesOwnKeys()
    {
        var nodes = new[] { "n0", "n1", "n2", "n3", "n4" };
        var ring = new HashRing(nodes, 100);
        var keys = Enumerable.Range(0, 1000).Select(i => $"key-{i}").ToList();
        var before = keys.ToDictionary(k => k, k => ring.GetNode(k));

        ring.RemoveNode("n2");

        int moved = 0;
        foreach (var k in keys)
        {
            var after = ring.GetNode(k);
            if (after != before[k])
            {
                moved++;
                Assert.Equal("n2", before[k]);
            }
            Assert.NotEqual("n2", after);
        }
        Assert.True(moved > 0);
    }
}
